from pathlib import Path
import json,html,base64,zlib,re,hashlib
C=Path(__file__).parent;R=C.parents[1];D=C/'research';O=R/'deliverables';O.mkdir(exist_ok=True)
P=json.loads((D/'packet.json').read_text());V=json.loads((C/'review/validation.json').read_text());FINAL='v1_r02_final';RUN=C/'runs'/FINAL;PRE=C/'review/previews'/FINAL;M=json.loads((RUN/'manifest.json').read_text());E=html.escape

def uri(p,mime='image/png'):return 'data:'+mime+';base64,'+base64.b64encode(Path(p).read_bytes()).decode()
def dl(p,label,name=None):return f'<a class="button" download="{E(name or Path(p).name)}" href="{uri(p,"application/octet-stream")}">{E(label)}</a>'
def pic(f,label,folder=PRE):return f'<figure><img loading="lazy" src="{uri(folder/f)}" alt="{E(label)}"><figcaption>{E(label)}</figcaption></figure>'
def table(head,rows):return '<div class="tablewrap"><table><thead><tr>'+''.join('<th>'+E(x)+'</th>' for x in head)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+str(x)+'</td>' for x in row)+'</tr>' for row in rows)+'</tbody></table></div>'
def pre(o):return '<pre>'+E(o if isinstance(o,str) else json.dumps(o,ensure_ascii=False,indent=2))+'</pre>'
CSS='''*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;color:#182b37;background:#f4f3ef;font:16px/1.8 system-ui,-apple-system,"Noto Sans CJK SC","Microsoft YaHei",sans-serif}a{color:#185b79;text-underline-offset:3px}button,.button,select{font:inherit}button,.button{display:inline-block;border:1px solid #b7b9ba;border-radius:7px;background:#fff;padding:8px 15px;text-decoration:none;cursor:pointer;color:#243844;margin:4px 6px 4px 0}button:hover,.button:hover{background:#d7eff0}button:focus-visible,a:focus-visible{outline:3px solid #187a89;outline-offset:3px}header{background:#152e3b;color:#fff;padding:42px max(5vw,20px)}header a{color:#aae5e6}.eyebrow{font-size:12px;letter-spacing:3px;color:#6bc8d0;font-weight:700}h1{font-size:clamp(38px,6vw,72px);line-height:1.15;margin:22px 0}h2{font-size:28px;line-height:1.4;margin:0 0 24px}h3{font-size:20px;margin-top:28px}p{max-width:75em}main{max-width:1260px;margin:auto;padding:0 28px 60px}section{padding:48px 0;border-bottom:1px solid #d4d9d8;scroll-margin-top:75px}nav{position:sticky;top:0;background:#fffef9ef;border-bottom:1px solid #d4d9d8;z-index:10;padding:10px max(4vw,16px);display:flex;gap:18px;overflow:auto;white-space:nowrap;font-size:14px}figure{margin:0;background:#fff;border:1px solid #d4d9d8;border-radius:10px;overflow:hidden}figure img{display:block;width:100%;max-height:760px;object-fit:contain;background:#e2e7e6}figcaption{padding:12px 16px;font-size:13px;line-height:1.6}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:22px}.grid.four{grid-template-columns:repeat(4,minmax(0,1fr))}.grid.four img{max-height:440px}.hero{display:grid;grid-template-columns:1.2fr .8fr;gap:40px;align-items:center}.hero figure img{max-height:660px}.hero figure{background:transparent;border:0;border-radius:12px}.lead{font-size:20px;line-height:1.8;color:#dce9eb}.tag{display:inline-block;border:1px solid #76858b;border-radius:20px;font-size:12px;padding:3px 10px;margin-right:6px}.metrics{display:flex;gap:24px;flex-wrap:wrap;margin:25px 0}.metrics b{font-size:30px;display:block}.metrics small{display:block;font-size:12px}.note{padding:18px 22px;background:#e8eeec;border-left:4px solid #547a7c;border-radius:0 7px 7px 0}.warn{background:#f4e4e9;border-left-color:#ae5077}.tablewrap{overflow:auto}table{border-collapse:collapse;width:100%;font-size:14px}td,th{padding:13px 14px;border-bottom:1px solid #d1d7d7;vertical-align:top;text-align:left}th{background:#e5ebea;font-weight:600}code,pre{font-family:ui-monospace,monospace}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#122b38;color:#e6eff1;padding:22px;border-radius:8px;max-height:560px;overflow:auto;font-size:13px;line-height:1.65}details{background:#fff;padding:14px 18px;border:1px solid #d4d9d8;border-radius:8px;margin:14px 0}summary{cursor:pointer;font-weight:600}.photos img{height:320px}.source{font-size:12px;overflow-wrap:anywhere;color:#425d6b}.status{font-size:13px;font-weight:700;color:#476f66}.muted{font-size:14px;color:#5b6e74}iframe{border:0;width:100%;height:750px;border-radius:12px;background:#183543}.compare{position:relative;max-width:100%;overflow:hidden;background:#dce4e5;border-radius:10px}.compare>img{display:block;width:100%}.compare .after{position:absolute;inset:0;clip-path:inset(0 50% 0 0)}.compare .after img{width:100%}.comparelabel{position:absolute;top:16px;background:#132f3bcc;color:#fff;padding:4px 14px;border-radius:5px}.comparelabel.right{right:16px}.comparelabel.left{left:16px}input[type=range]{width:100%;accent-color:#187a89}.boxstage{height:450px;perspective:1000px;overflow:hidden;background:#152e3b;border-radius:10px}.octobox{width:160px;height:260px;position:relative;margin:85px auto;transform-style:preserve-3d;transform:rotateX(-8deg) rotateY(0deg);transition:transform .25s}.octobox .panel{position:absolute;width:160px;height:260px;background:#fff;border:2px solid #5aa9ba;backface-visibility:visible;opacity:.97;transform:rotateY(calc(var(--i)*45deg)) translateZ(200px)}.panel img{width:100%;height:222px;object-fit:cover}.panel p{margin:0;font-size:11px;padding:4px;color:#142e3a;text-align:center}.flow{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}.flow div{background:#e5edeb;padding:14px;border-top:3px solid #187a89}.flow b{display:block}footer{padding:30px;color:#668;font-size:12px;text-align:center}.license{font-size:12px}.downloadset{display:flex;gap:8px;flex-wrap:wrap}@media(max-width:760px){.hero,.grid,.grid.four{grid-template-columns:1fr}.flow{grid-template-columns:1fr 1fr}main{padding:0 18px 40px}header{padding:30px 20px}.hero figure{max-width:380px;margin:auto}.grid.four{grid-template-columns:repeat(2,minmax(0,1fr))}iframe{height:650px}h2{font-size:24px}td,th{padding:9px}nav{gap:15px}.metrics{gap:18px}}@media print{nav,.interactive,button{display:none}section{break-inside:avoid}body{background:white}header{color:black;background:white}.lead{color:black}}'''

def doc(title,body):return '<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>'+E(title)+'</title><style>'+CSS+'</style></head><body>'+body+'</body></html>'
