vtext=(C/'review/assets/render_shader_reference.html').read_text();js=re.search(r'<script>([\s\S]*)</script>',vtext)[1]
js=js.replace("document.querySelector('canvas')","document.getElementById('c')").replace("if(vEmission>.5)c=mix(vec3(.87,.96,.83),vec3(.84,1.,.83),uNight);","if(vEmission>.5)c=vColor;")
asset={n:base64.b64encode(zlib.compress((PRE/'scene'/n).read_bytes(),9)).decode() for n in ['opaque.bin','glass.bin','blocklight.bin']}
meta=json.loads((PRE/'scene/scene.json').read_text());inject='const BINS='+json.dumps(asset)+';\nconst META='+json.dumps(meta)+';\nasync function inflate(n){const b=Uint8Array.from(atob(BINS[n]),c=>c.charCodeAt(0));return await new Response(new Blob([b]).stream().pipeThrough(new DecompressionStream("deflate"))).arrayBuffer()}\n'
start=js.index('async function init(){');end=js.index('lightTex=gl.createTexture()',start)
js=js[:start]+'''async function init(){[opaque,glass]=await Promise.all(['opaque','glass'].map(async n=>mesh(new Float32Array(await inflate(n+'.bin')))));meta=META;const light=new Uint8Array(await inflate('blocklight.bin'));
'''+js[end:]
js=js.replace('center=[64,125,110]','center=meta.size_xyz.map(v=>v/2)').replace("cv.style.width=o.width+'px';cv.style.height=o.height+'px';","cv.style.width='100%';cv.style.height='100%';")
js=js.replace("init().catch(e=>{window.error=e.stack;throw e});",'''let pending=false;function update(){if(!window.ready||pending)return;pending=true;requestAnimationFrame(async()=>{try{const yaw=Number(document.getElementById('yaw').value)*Math.PI/180;const zoom=Number(document.getElementById('zoom').value);const mode=document.getElementById('mode').value;const width=Math.min(1200,innerWidth),height=Math.min(1100,innerHeight-125);let target=[36.5,117,36.5],spanZ=262/zoom,rise=38,dist=340,extra={};if(mode==='facade'){target=[36.5,95,36.5];spanZ=58/zoom;rise=25;dist=180}if(mode==='aperture'){target=[36.5,218,36.5];spanZ=48/zoom;rise=25;dist=180}if(mode==='section'){target=[36.5,100,36.5];spanZ=42/zoom;rise=12;extra={cutX:37,cutY:120,minY:80}}let eye=[36.5+Math.sin(yaw)*dist,target[1]+rise,36.5+Math.cos(yaw)*dist];if(mode==='top'){target=[36.5,3,36.5];eye=[36.5,500,36.5];spanZ=78/zoom}await window.render({width,height,spanZ,spanX:spanZ*width/height,eye,target,ortho:true,night:document.getElementById('night').checked,concept:false,...extra});document.getElementById('msg').textContent='NBT 同源几何 · 拖动旋转 · 玻璃及照明为近似预览';}catch(e){window.error=e.stack;document.getElementById('msg').textContent='实时预览不可用：'+e.message}pending=false})}
for(const el of document.querySelectorAll('input,select'))el.addEventListener('input',update);let drag=null;cv.addEventListener('pointerdown',e=>{drag=[e.clientX,Number(document.getElementById('yaw').value)];cv.setPointerCapture(e.pointerId)});cv.addEventListener('pointermove',e=>{if(drag){document.getElementById('yaw').value=(drag[1]+(e.clientX-drag[0])*.5+720)%360;update()}});cv.addEventListener('pointerup',()=>drag=null);window.addEventListener('resize',update);init().then(update).catch(e=>{window.error=e.stack;document.getElementById('msg').textContent='实时预览不可用：'+e.message});''')
viewer='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>上海环球金融中心 · NBT 几何查看</title><style>body{margin:0;background:#142f3c;color:#fff;font:13px system-ui}#controls{height:125px;padding:12px 18px;box-sizing:border-box}select{max-width:150px;padding:4px}label{display:inline-block;margin:4px 14px 4px 0}input[type=range]{width:100px;vertical-align:middle;accent-color:#5aa9ba}#c{display:block;touch-action:none}#msg{font-size:12px;color:#c5d7de}</style><div id="controls"><label>视图 <select id="mode"><option value="all">全塔</option><option value="facade">幕墙</option><option value="aperture">顶孔</option><option value="top">真俯视</option><option value="section">幕墙剖切</option></select></label><label><input id="night" type="checkbox">夜景</label><label>旋转 <input id="yaw" type="range" min="0" max="360" value="45"></label><label>缩放 <input id="zoom" type="range" min="0.7" max="2" step="0.05" value="1"></label><div id="msg">加载内嵌几何…</div></div><canvas id="c"></canvas><script>'''+inject+js+'</script></html>'
